-- A venue is a place where events happen: a hall, an arena, a club, a theatre.
-- Its layouts (seated and standing sections) are separate tables, added in M1 step 6.
--
-- Optional columns allow NULL but reject empty or blank text: a CHECK passes when its expression is
-- NULL, so the same check works for required columns (with NOT NULL) and optional ones (without).
CREATE TABLE venues (
    -- Random UUID, generated by Postgres. IDs appear in URLs, and random ones reveal nothing.
    id            uuid         PRIMARY KEY DEFAULT gen_random_uuid(),
    name          text         NOT NULL CHECK (length(btrim(name)) BETWEEN 1 AND 200),
    -- Box office hours, parking, accessibility and other visitor information.
    description   text                  CHECK (length(btrim(description)) BETWEEN 1 AND 5000),

    -- International address, the same shape Stripe uses. Not every country has regions or postal
    -- codes, so those are optional.
    address_line1 text         NOT NULL CHECK (length(btrim(address_line1)) BETWEEN 1 AND 200),
    address_line2 text                  CHECK (length(btrim(address_line2)) BETWEEN 1 AND 200),
    city          text         NOT NULL CHECK (length(btrim(city)) BETWEEN 1 AND 100),
    region        text                  CHECK (length(btrim(region)) BETWEEN 1 AND 100),
    postal_code   text                  CHECK (length(btrim(postal_code)) BETWEEN 1 AND 20),
    -- ISO 3166-1 alpha-2, e.g. TR or DE. text, not char(2): char(n) pads with spaces.
    country_code  text         NOT NULL CHECK (country_code ~ '^[A-Z]{2}$'),

    -- Optional map position, about 10 cm precise. Set both or neither (last CHECK below).
    latitude      numeric(8,6)          CHECK (latitude BETWEEN -90 AND 90),
    longitude     numeric(9,6)          CHECK (longitude BETWEEN -180 AND 180),

    -- IANA time zone name, e.g. Europe/Istanbul, so event times can be entered and shown in local
    -- time. Postgres can't easily check that the name exists; the Go code does (M1 step 5).
    timezone      text         NOT NULL CHECK (length(btrim(timezone)) BETWEEN 1 AND 64),

    -- Maximum occupancy, if known. Publishing an event checks its tickets against it (M1 step 10).
    capacity      integer               CHECK (capacity > 0),

    created_at    timestamptz  NOT NULL DEFAULT now(),
    -- Set by the update queries themselves; there is no trigger.
    updated_at    timestamptz  NOT NULL DEFAULT now(),

    CONSTRAINT venues_coordinates_together CHECK ((latitude IS NULL) = (longitude IS NULL))
);
